class SmoothWeightedRoundRobin:
    def __init__(self, servers):
        self._servers = dict(servers)
        self._current_weights = {s: 0 for s in self._servers}
        self._total_weight = sum(self._servers.values())

    def select(self):
        if not self._servers or self._total_weight <= 0:
            return None
        best = None
        best_weight = -float('inf')
        for s, w in self._servers.items():
            self._current_weights[s] += w
            if self._current_weights[s] > best_weight:
                best_weight = self._current_weights[s]
                best = s
        self._current_weights[best] -= self._total_weight
        return best

    def reset(self):
        for s in self._servers:
            self._current_weights[s] = 0
